heartbeat();
console.log('worker started');

while (!stopping) {
  heartbeat();
  let job: Record<string, unknown> | undefined;
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = db.prepare(`SELECT * FROM jobs WHERE status='queued' AND available_at<=? ORDER BY created_at,id LIMIT 1`).get(Date.now()) as Record<string, unknown> | undefined;
    if (row) {
      const resumed = Number(row.resume_attempt) > 0;
      const attempts = resumed ? Number(row.attempts) : Number(row.attempts) + 1;
      db.prepare(`UPDATE jobs SET status='running', attempts=?, resume_attempt=0, progress_completed=0, updated_at=? WHERE id=?`).run(attempts, new Date().toISOString(), String(row.id));
      job = { ...row, attempts, progress_completed: 0 };
    }
    db.exec('COMMIT');
  } catch (e) { db.exec('ROLLBACK'); throw e; }
  if (!job) { await sleep(100); continue; }

  const id = String(job.id), steps = Number(job.steps), attempts = Number(job.attempts);
  const failAttempts = Number(job.fail_attempts);
  let failed = attempts <= failAttempts;
  for (let step = 1; step <= steps && !stopping; step++) {
    if (failed) break; // simulated dependency failure happens before the first progress update
    await sleep(100);
    if (stopping) break;
    db.prepare(`UPDATE jobs SET progress_completed=?, updated_at=? WHERE id=? AND status='running'`)
      .run(step, new Date().toISOString(), id);
  }
  if (stopping) break;
  if (failed) {
    const now = new Date().toISOString();
    if (attempts >= 3) {
      db.prepare(`UPDATE jobs SET status='failed', error='transient failure', result_output=NULL, updated_at=? WHERE id=?`).run(now, id);
    } else {
      db.prepare(`UPDATE jobs SET status='queued', error=NULL, progress_completed=0, available_at=?, updated_at=? WHERE id=?`)
        .run(Date.now() + 500, now, id);
    }
  } else {
    const output = String(job.input).toUpperCase();
    db.prepare(`UPDATE jobs SET status='completed', result_output=?, error=NULL, progress_completed=steps, updated_at=? WHERE id=?`)
      .run(output, new Date().toISOString(), id);
  }
}
