<body>
  <h1>Job tracker</h1>
  <form data-testid="job-form" id="job-form">
    <label>Input <input data-testid="job-input" name="input"></label>
    <label>Steps <input data-testid="job-steps" name="steps" type="number" value="5"></label>
    <label>Fail attempts <input data-testid="job-fail-attempts" name="failAttempts" type="number" value="0"></label>
    <button data-testid="job-submit" type="submit">Submit job</button>
    <div data-testid="form-error" id="form-error" role="alert"></div>
  </form>
  <h2>Jobs</h2>
  <ul data-testid="job-list" id="job-list"></ul>
  <script>
    const list = document.querySelector('#job-list');
    const form = document.querySelector('#job-form');
    const errorRegion = document.querySelector('#form-error');
    function render(jobs) {
      list.replaceChildren(...jobs.map(job => {
        const item = document.createElement('li'); item.dataset.testid = 'job-item'; item.dataset.jobId = job.id;
        const title = document.createElement('strong'); title.textContent = job.input;
        const status = document.createElement('span'); status.dataset.testid = 'job-status'; status.textContent = job.status;
        const progress = document.createElement('span'); progress.dataset.testid = 'job-progress'; progress.textContent = `${job.progress.completed}/${job.progress.total}`;
        const result = document.createElement('div'); result.dataset.testid = 'job-result'; result.textContent = job.result?.output ?? job.error ?? '';
        item.append(title, document.createTextNode(' — '), status, document.createTextNode(' · '), progress, result);
        return item;
      }));
    }
    async function refresh() {
      try { const response = await fetch('/api/jobs'); if (response.ok) render((await response.json()).jobs); } catch (_) {}
    }
    form.addEventListener('submit', async event => {
      event.preventDefault(); errorRegion.textContent = '';
      const data = new FormData(form);
      const payload = { input: data.get('input'), steps: Number(data.get('steps')), failAttempts: Number(data.get('failAttempts')) };
      try {
        const response = await fetch('/api/jobs', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
        const body = await response.json();
        if (!response.ok) {
          const details = body.error?.fields?.map(field => `${field.field}: ${field.message}`).join(' ') ?? body.error?.message ?? 'Request failed.';
          errorRegion.textContent = details;
        } else { form.elements.input.value = ''; await refresh(); }
      } catch (_) { errorRegion.textContent = 'Could not submit the job.'; }
    });
    refresh(); setInterval(refresh, 500);
  </script>
</body>
</html>
